 static string StorageRoot(){string path=Path.Combine(Environment.GetEnvironmentVariable("ASHFALL_RECEIPT_TEST_ROOT")??MissingFixtureRoot(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"fixture-name.txt"),new System.Diagnostics.StackTrace().GetFrame(1).GetMethod().Name);return path;}
 static string MissingFixtureRoot(){throw new InvalidOperationException("Run storage cases through check_lan_current.py so fixtures stay with their results");}
 static CommandContext DC(string id,long tick,string actor="host",long epoch=0){return new CommandContext("durable",actor,id,tick,epoch,true);}
 static HealthService DH(ReceiptPorts ports,long epoch=0){return new HealthService("durable",epoch,0,true,ports,ports,ports,60,5,0);}
 static FileHealthImageStore DS(string root,long epoch=0,long disk=1048576,int image=2097152,int epochs=128){return new FileHealthImageStore(root,"durable",epoch,new string('b',64),disk,image,epochs);}
 static bool StorageThrows(Action operation){try{operation();return false;}catch(HealthStorageException){return true;}catch(InvalidDataException){return true;}catch(IOException){return true;}}
 static void DurablePressureRecovery(){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64),64);Need(h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0).Accepted,"Durable spawn");h.DrainTransitions();DamageReceipt first=null;string oldManifest=null;
  for(int i=0;i<40;i++){var receipt=h.ApplyDamage(DC("c"+i,100+i*100),"logical-"+i,"p",h.Read("p").Revision,.01f,0,false);Need(receipt.Result.Accepted,"All pressure writes accepted");if(i==0){first=receipt;oldManifest=h.DurableManifest;}if(i<39)h.DrainTransitions();}
  float hp=h.Read("p").Health;Need(StorageThrows(delegate{store.RequireManifest(oldManifest);}),"Older checkpoint manifest cannot roll the authority back");Need(Directory.GetFiles(store.DirectoryPath).Length==5,"Successful writes reuse two managed slots without archive growth");string manifest=h.DurableManifest;store.Dispose();
  var reopened=DS(root);var recovered=DH(ports);recovered.EnableDurableImages(reopened,new string('b',64),64);Need(recovered.Read("p").Health==hp&&recovered.PendingTransitionCount==1,"Restart restores Health and the atomic producer outbox");var duplicate=recovered.ApplyDamage(DC("fresh",10000),"logical-0","p",recovered.Read("p").Revision,90,0,false);Need(duplicate.Snapshot.Health==first.Snapshot.Health&&recovered.Read("p").Health==hp&&recovered.PendingTransitionCount==1,"Old exact outcome survives pruning/restart without another mutation or publication");Need(StorageThrows(delegate{recovered.RecoverDurableImages(oldManifest,64);}),"Recovery rejects stale manifest");recovered.RecoverDurableImages(manifest,64);recovered.ReleaseDurableImages();
  var sealedStore=DS(root);var closed=DH(ports);closed.EnableDurableImages(sealedStore,new string('b',64));Need(!closed.ApplyDamage(DC("old",10001),"logical-0","p",closed.Read("p").Revision,90,0,false).Result.Accepted,"Persisted epoch closure rejects old authority replay");sealedStore.Dispose();var wrong=DS(root);Need(StorageThrows(delegate{DH(ports,1).EnableDurableImages(wrong,new string('b',64));}),"An old image cannot be adopted into a new epoch");wrong.Dispose();
 }
 static void DurableLimitsAndGains(){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64),4);h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);h.DrainTransitions();for(int i=0;i<4;i++){Need(h.ApplyDamage(DC("c"+i,i+2),"hit"+i,"p",h.Read("p").Revision,.1f,0,false).Result.Accepted,"Within resident quota");h.DrainTransitions();}float hp=h.Read("p").Health;Need(StorageThrows(delegate{h.ApplyDamage(DC("over",10),"over","p",h.Read("p").Revision,1,0,false);})&&h.Read("p").Health==hp&&h.StorageFailure!=null,"Resident pressure freezes new mutation before exposure");Need(h.ApplyDamage(DC("retry",11),"hit0","p",h.Read("p").Revision,80,0,false).Result.Accepted&&h.Read("p").Health==hp,"Exact duplicate remains available while degraded");h.RecoverDurableImages(h.DurableManifest,16);Need(h.ApplyDamage(DC("resumed",12),"over","p",h.Read("p").Revision,1,0,false).Result.Accepted,"Explicit raised quota recovers without forgetting history");h.DrainTransitions();var before=h.Read("p");HealthService.PreparedGain gain;Need(h.PrepareGain(DC("gain-command",13,"p"),"gain-id","p",before.Revision,before.LifeGeneration,before.ConnectionGeneration,100,0,out gain)&&gain.Validate(),"Prepared gain retains original validation");gain.CommitValidated();gain.Abort();float full=h.Read("p").Health;store.Dispose();var again=DS(root);var restored=DH(ports);restored.EnableDurableImages(again,new string('b',64),16);var old=restored.FindGain(DC("gain-query",100,"p"),"gain-id","p");Need(old!=null&&old.Outcome==GainOutcome.Applied&&restored.Read("p").Health==full,"Prepared gain outcome and Health restart atomically");Need(StorageThrows(delegate{restored.CreateCheckpoint(DC("raw",101),new string('b',64));}),"Storage-bound owner cannot export a stale raw checkpoint");again.Dispose();
  string small=StorageRoot();var limited=DS(small,0,4096);var bounded=DH(ports);bounded.EnableDurableImages(limited,new string('b',64));bool failed=false;try{bounded.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);for(int i=0;i<100;i++){bounded.ApplyDamage(DC("long"+i,2+i),new string('x',120)+i,"p",bounded.Read("p").Revision,.01f,0,false);bounded.DrainTransitions();}}catch(HealthStorageException){failed=true;}Need(failed&&bounded.StorageFailure!=null,"Disk quota explicitly stops without dropping ledger history");limited.Dispose();string imageRoot=StorageRoot();var imageStore=DS(imageRoot,0,1048576,512);var imageHealth=DH(ports);imageHealth.EnableDurableImages(imageStore,new string('b',64));Need(StorageThrows(delegate{imageHealth.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);imageHealth.ApplyDamage(DC("large",2),new string('z',128),"p",imageHealth.Read("p").Revision,1,0,false);}),"Image quota cannot publish an oversized unjournaled mutation");imageStore.Dispose();
 }
 static void DurableCrashCorruption(){foreach(string point in new[]{"before-image","image-flushed","image-installed","head-flushed","head-installed"}){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64));h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);h.DrainTransitions();store.FaultInjection=delegate(string at){if(at==point)throw new IOException("injected "+at);};Need(StorageThrows(delegate{h.ApplyDamage(DC("hit",2),"once","p",h.Read("p").Revision,1,0,false);}),"Crash boundary surfaces "+point);Need(h.Read("p").Health==(point=="head-installed"?99:100),"Only the atomic committed head determines recovery "+point);store.Dispose();var next=DS(root);var recovered=DH(ports);recovered.EnableDurableImages(next,new string('b',64));Need(recovered.Read("p").Health==(point=="head-installed"?99:100),"Restart uses committed head "+point);if(point=="head-installed")Need(recovered.ApplyDamage(DC("retry",500),"once","p",recovered.Read("p").Revision,80,0,false).Snapshot.Health==99&&recovered.Read("p").Health==99,"Ambiguous caller failure cannot reapply committed hit");next.Dispose();}
  foreach(string file in new[]{"head","image0","image1","identity"}){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64));h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);string dir=store.DirectoryPath;store.Dispose();string target=Path.Combine(dir,file);if(file.StartsWith("image")){// Corrupt both slots so the current head always encounters corruption.
    foreach(string name in new[]{"image0","image1"})File.WriteAllBytes(Path.Combine(dir,name),new byte[]{255});
   }else File.WriteAllBytes(target,new byte[]{255});Need(StorageThrows(delegate{using(var invalid=DS(root)){invalid.Read();}}),"Corruption cannot silently select an older prefix: "+file);}
  string epochs=StorageRoot();using(var e0=DS(epochs,0,1048576,2097152,2)){var h=DH(new ReceiptPorts());h.EnableDurableImages(e0,new string('b',64));}using(var e1=DS(epochs,1,1048576,2097152,2)){}Need(StorageThrows(delegate{using(var e2=DS(epochs,2,1048576,2097152,2)){};}),"Epoch retention is bounded without automatic archive deletion");Need(Directory.GetDirectories(epochs).Length==2,"Historical epoch data remains present");
 }
 static void DurableLanComposition(){using(var pair=new Pair()){string root=StorageRoot();pair.Host.BindHealthStorage(delegate(string session,long epoch){return new FileHealthImageStore(root,session,epoch,new string('a',64));},64);string hash=new string('b',64);StartRound(pair,new HazardWorld(),R24PlayableMatchRules.ForPreset("free_for_all","range").With("zone_enabled",false).With("protection",0),hash);for(int i=0;i<4;i++)KeepRaw(pair,hash,0,8);R24LanHealthState before;pair.Host.TryReadHealth(pair.Client.OwnActor,out before);Need(pair.Host.ApplyHostHealthLoss(pair.Client.OwnActor,before.Revision,1,0,false).Accepted,"Actual LAN Health mutation uses the bound durable path");Need(Directory.GetFiles(root,"head",SearchOption.AllDirectories).Length==1,"LAN creates a committed epoch image");}} 
 static void DurableProcessCrash(){string worker=Environment.GetEnvironmentVariable("ASHFALL_RECEIPT_CRASH_WORKER");Need(!String.IsNullOrEmpty(worker)&&File.Exists(worker),"CPU process-crash worker compiled");foreach(string point in new[]{"before-image","image-flushed","image-installed","head-flushed","head-installed"}){string root=StorageRoot();var info=new System.Diagnostics.ProcessStartInfo(worker,"\""+root+"\" "+point){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden};using(var process=System.Diagnostics.Process.Start(info)){if(!process.WaitForExit(10000)){process.Kill();process.WaitForExit();throw new Exception("task-owned crash worker timeout");}Need(process.ExitCode==71,"Worker exited inside transaction without rollback/finally: "+point);}var ports=new ReceiptPorts();using(var store=DS(root)){var h=DH(ports);h.EnableDurableImages(store,new string('b',64));Need(h.Read("p").Health==(point=="head-installed"?99:100),"Physical restart uses only committed head: "+point);Console.WriteLine("PROCESS CRASH "+point+" exit=71 hp="+h.Read("p").Health);}}}
 static void DurableStaleTokensAndPartial(){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64));h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,90,0);h.DrainTransitions();var before=h.Read("p");HealthService.PreparedGain gain;Need(h.PrepareGain(DC("gain",2,"p"),"gain","p",before.Revision,before.LifeGeneration,before.ConnectionGeneration,10,0,out gain)&&gain.Validate(),"Validated gain before persistence failure");store.FaultInjection=delegate(string point){if(point=="before-image")throw new IOException("fail prepared commit");};Need(StorageThrows(delegate{gain.CommitValidated();})&&h.Read("p").Health==90,"Failed prepared gain never exposes its speculative Health");store.FaultInjection=null;h.RecoverDurableImages(h.DurableManifest);bool stale=false;try{gain.CommitValidated();}catch(InvalidOperationException e){stale=e.Message=="stale durable token";}Need(stale&&!gain.Validate()&&h.Read("p").Health==90,"Recovered owner fences previously committed-in-memory tokens");string dir=store.DirectoryPath;File.WriteAllBytes(Path.Combine(dir,"image.pending"),new byte[]{1,2,3});Need(StorageThrows(delegate{h.ApplyLoss(DC("partial",3),"p",h.Read("p").Revision,1,0,false);})&&h.Read("p").Health==90,"Partial writes are not accepted or silently overwritten");File.Move(Path.Combine(dir,"image.pending"),Path.Combine(dir,"explicitly-quarantined-partial"));h.RecoverDurableImages(h.DurableManifest);Need(h.ApplyLoss(DC("resume",4),"p",h.Read("p").Revision,1,0,false).Accepted,"Explicit quarantine permits exact recovery without deleting evidence");Need(File.Exists(Path.Combine(dir,"explicitly-quarantined-partial")),"Partial evidence is retained");Need(StorageThrows(delegate{using(var duplicate=DS(root)){};}),"Exclusive epoch ownership denies duplicate writers");Need(StorageThrows(delegate{h.RecoverDurableImages(h.DurableManifest,4096,33562624);}),"Resident byte budget cannot be bypassed by a key quota");store.Dispose();}
 static void DurableJointSessionFailure(){using(var pair=new Pair()){string root=StorageRoot();FileHealthImageStore store=null;pair.Host.BindHealthStorage(delegate(string session,long epoch){store=new FileHealthImageStore(root,session,epoch,new string('a',64));return store;});string hash=new string('b',64);var rules=R24PlayableMatchRules.ForPreset("free_for_all","range").With("zone_enabled",false).With("protection",0).With("respawn_delay",1);StartRound(pair,new HazardWorld(),rules,hash);for(int i=0;i<3;i++)KeepRaw(pair,hash,0,8);R24LanHealthState dead;pair.Host.TryReadHealth(pair.Client.OwnActor,out dead);pair.Host.ApplyHostHealthLoss(pair.Client.OwnActor,dead.Revision,dead.Health,dead.Shield,false);pair.Host.TryReadHealth(pair.Client.OwnActor,out dead);int revision=pair.Host.ReadAuthorityMember(pair.Client.OwnActor).SpawnRevision;pair.Now=dead.RespawnAt+.1;var ports=new ReceiptPorts{Time=pair.Now};store.FaultInjection=delegate(string point){if(point!="image-flushed")return;var data=File.ReadAllBytes(Path.Combine(store.DirectoryPath,"image.pending"));HealthService candidate;var context=new CommandContext(pair.Host.SessionId,"host","inspect",Int64.MaxValue,pair.Host.Epoch,true);if(HealthService.TryRestoreCheckpoint(context,new string('a',64),FileHealthImageStore.Digest(data),data,rules.Teams,true,ports,ports,ports,out candidate,rules.DownedSeconds,rules.RespawnDelay,rules.Protection)&&candidate.Read(dead.CanonicalActor).Life==LifeState.Alive)throw new IOException("joint respawn persistence failure");};Need(StorageThrows(delegate{pair.Host.Tick(pair.Now);}),"Durable Health failure interrupts the actual joint Session respawn");Need(pair.Host.ReadAuthorityMember(pair.Client.OwnActor).SpawnRevision==revision&&pair.Host.ReadAuthorityMember(pair.Client.OwnActor).Life==Ashfall.Modules.Sessions.SessionLife.Eliminated,"Session placement/life never commits after failed Health storage");Need(pair.Host.HealthStorageFailure!=null,"LAN exposes deterministic degraded storage state");}}
 
 static void DurableExactTerminalOutcomes(){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var h=DH(ports);h.EnableDurableImages(store,new string('b',64));h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);h.DrainTransitions();var rejected=h.ApplyDamage(DC("reject",2),"rejected","p",h.Read("p").Revision,0,0,false);Need(!rejected.Result.Accepted,"Invalid loss receives terminal rejected outcome");HealthService.PreparedGain capped;var full=h.Read("p");Need(h.PrepareGain(DC("capped",3,"p"),"capped","p",full.Revision,full.LifeGeneration,full.ConnectionGeneration,10,0,out capped)&&capped.Validate(),"Capped gain uses existing prepared path");Need(capped.CommitValidated().Outcome==GainOutcome.CappedNoOp,"Capped no-op persisted exactly");for(int i=0;i<5;i++){h.ApplyDamage(DC("hit"+i,500+i*500),"hit"+i,"p",h.Read("p").Revision,1,0,false);h.DrainTransitions();}store.Dispose();using(var reopened=DS(root)){var recovered=DH(ports);recovered.EnableDurableImages(reopened,new string('b',64));var terminal=recovered.ApplyDamage(DC("fresh-rejected-retry",5000),"rejected","p",recovered.Read("p").Revision,50,0,false);Need(!terminal.Result.Accepted&&terminal.Result.Reason==rejected.Result.Reason&&terminal.Snapshot.Health==100&&recovered.Read("p").Health==95,"Rejected outcome and original snapshot remain exact after state changes/pruning/restart");Need(recovered.FindGain(DC("fresh-gain",5001,"p"),"capped","p").Outcome==GainOutcome.CappedNoOp,"Capped outcome never becomes a later gain");var conflict=recovered.FindDamage(DC("conflict",5002),"hit0","another-target");Need(conflict!=null&&!conflict.Result.Accepted&&conflict.Result.Reason=="identity-conflict"&&recovered.Read("p").Health==95,"Logical identity cannot be rebound to another target");}}
 static void DurableSharedWriterAndReopen(){string root=StorageRoot();var ports=new ReceiptPorts();var store=DS(root);var first=DH(ports);first.EnableDurableImages(store,new string('b',64));var stale=DH(ports);stale.EnableDurableImages(store,new string('b',64));first.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);Need(StorageThrows(delegate{stale.RegisterConfiguredSpawn(DC("overwrite",2),"p",-1,false,50,0);}),"Stale in-process owner cannot overwrite a newer committed prefix");Need(first.Read("p").Health==100&&stale.Read("p").Health==100,"Stale writer restores committed state and freezes");store.Dispose();string lowRoot=StorageRoot();var low=DS(lowRoot,0,4096);var h=DH(ports);h.EnableDurableImages(low,new string('b',64));try{h.RegisterConfiguredSpawn(DC("spawn",1),"p",-1,false,100,0);for(int i=0;i<100;i++){h.ApplyDamage(DC("h"+i,i+2),new string('q',120)+i,"p",h.Read("p").Revision,.1f,0,false);h.DrainTransitions();}}catch(HealthStorageException){}Need(h.StorageFailure!=null,"Quota failure available for explicit reopen");string expected=h.DurableManifest;h.ReopenDurableImages(delegate{return DS(lowRoot,0,1048576);},expected);Need(h.ApplyDamage(DC("resume-reopened",1000),"resume-reopened","p",h.Read("p").Revision,.1f,0,false).Result.Accepted,"Reopened larger disk budget recovers the existing epoch without dropping old receipts");h.ReleaseDurableImages();}

