 static void DurableShutdownFailure(){var pair=new Pair();string root=StorageRoot();FileHealthImageStore store=null;pair.Host.BindHealthStorage(delegate(string session,long epoch){store=new FileHealthImageStore(root,session,epoch,new string('a',64));return store;});string hash=new string('b',64);StartRound(pair,new HazardWorld(),R24PlayableMatchRules.ForPreset("free_for_all","range").With("zone_enabled",false),hash);for(int i=0;i<3;i++)KeepRaw(pair,hash,0,8);store.FaultInjection=delegate(string point){if(point=="before-image")throw new IOException("shutdown storage failure");};pair.Host.Dispose();Need(pair.Host.State==R24LanLobbyState.Offline&&pair.Host.HealthStorageFailure!=null&&pair.Host.Status.Contains("shutdown storage failure"),"Shutdown retires authority and retains storage failure for the UI");pair.Dispose();}

